PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE COLLATE NOCASE, display_name TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','manager','member','viewer')), active INTEGER NOT NULL DEFAULT 1, daily_limit INTEGER NOT NULL DEFAULT 20, must_change_password INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts (id TEXT PRIMARY KEY, bucket TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS login_bucket ON login_attempts(bucket,created_at);
CREATE TABLE IF NOT EXISTS workspaces (id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS memberships (workspace_id TEXT NOT NULL REFERENCES workspaces(id), user_id TEXT NOT NULL REFERENCES users(id), PRIMARY KEY(workspace_id,user_id));
CREATE TABLE IF NOT EXISTS settings (id TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS advertisers (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), name TEXT NOT NULL, profile_md TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS advertiser_versions (id TEXT PRIMARY KEY, advertiser_id TEXT NOT NULL REFERENCES advertisers(id), version INTEGER NOT NULL, profile_md TEXT NOT NULL, user_id TEXT, created_at TEXT NOT NULL, UNIQUE(advertiser_id,version));
CREATE TABLE IF NOT EXISTS leads (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), advertiser_id TEXT NOT NULL REFERENCES advertisers(id), name TEXT NOT NULL DEFAULT '', company TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', website TEXT NOT NULL DEFAULT '', country TEXT NOT NULL DEFAULT '', city TEXT NOT NULL DEFAULT '', product TEXT NOT NULL DEFAULT '', business_type TEXT NOT NULL DEFAULT '', customization TEXT NOT NULL DEFAULT '', raw TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL DEFAULT 'new', owner_id TEXT REFERENCES users(id), notes TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL DEFAULT 1, match_level INTEGER, priority INTEGER, industry TEXT NOT NULL DEFAULT '', fit TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS lead_workspace ON leads(workspace_id,advertiser_id,updated_at);
CREATE TABLE IF NOT EXISTS lead_versions (id TEXT PRIMARY KEY, lead_id TEXT NOT NULL REFERENCES leads(id), version INTEGER NOT NULL, snapshot TEXT NOT NULL, user_id TEXT, created_at TEXT NOT NULL, UNIQUE(lead_id,version));
CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), lead_id TEXT REFERENCES leads(id), advertiser_id TEXT NOT NULL REFERENCES advertisers(id), user_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL, status TEXT NOT NULL, stage TEXT NOT NULL, error TEXT, model TEXT NOT NULL, profile_version INTEGER NOT NULL, lead_version INTEGER, input_json TEXT NOT NULL DEFAULT '{}', input_tokens INTEGER NOT NULL DEFAULT 0, output_tokens INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_lead_job ON jobs(lead_id) WHERE status IN ('queued','running') AND lead_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS one_active_profile_job ON jobs(advertiser_id) WHERE status IN ('queued','running') AND kind='profile';
CREATE TABLE IF NOT EXISTS job_payloads (job_id TEXT NOT NULL REFERENCES jobs(id), seq INTEGER NOT NULL, content TEXT NOT NULL, PRIMARY KEY(job_id,seq));
CREATE TABLE IF NOT EXISTS reports (id TEXT PRIMARY KEY, lead_id TEXT NOT NULL REFERENCES leads(id), job_id TEXT NOT NULL UNIQUE REFERENCES jobs(id), content_md TEXT NOT NULL, result_json TEXT NOT NULL, evidence_json TEXT NOT NULL, model TEXT NOT NULL, profile_version INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY, workspace_id TEXT, user_id TEXT, action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, details TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS events_workspace ON audit_events(workspace_id,created_at);
